import type { Metadata } from 'next'
import { notFound } from 'next/navigation'
import { BackButton } from '@/components/BackButton'
import {
  getComments,
  getPost,
  getPosts,
  isBlogPost,
  type BlogPost,
} from '@/lib/posts'

export const revalidate = 300

type BlogPostPageProps = PageProps<'/blog/[id]'>

export async function generateStaticParams(): Promise<Array<{ id: string }>> {
  const posts = await getPosts(revalidate)

  return posts.slice(0, 10).map((post) => ({ id: post.id.toString() }))
}

async function getValidPost(id: string): Promise<BlogPost | null> {
  try {
    const post = await getPost(id)
    return isBlogPost(post) ? post : null
  } catch {
    return null
  }
}

export async function generateMetadata({
  params,
}: BlogPostPageProps): Promise<Metadata> {
  const { id } = await params
  const post = await getValidPost(id)

  if (!post) {
    return { title: 'Post Not Found' }
  }

  const description = post.body.substring(0, 160)

  return {
    title: post.title,
    description,
    openGraph: {
      title: post.title,
      description,
    },
  }
}

export default async function BlogPostPage({ params }: BlogPostPageProps) {
  const { id } = await params
  const post = await getValidPost(id)

  if (!post) {
    notFound()
  }

  let comments

  try {
    comments = await getComments(id)
  } catch {
    notFound()
  }

  return (
    <article>
      <BackButton />

      <h1>{post.title}</h1>
      <p>{post.body}</p>

      <h2>Comments ({comments.length})</h2>
      <div className="comments">
        {comments.map((comment) => (
          <div key={comment.id} className="comment">
            <h3>{comment.name}</h3>
            <p>{comment.body}</p>
            <small>By: {comment.email}</small>
          </div>
        ))}
      </div>
    </article>
  )
}
import type { PostInput, UpdatedPost } from '@/lib/posts'

type PostRouteContext = RouteContext<'/api/posts/[id]'>

function parsePostId(id: string): number | null {
  if (!/^\d+$/.test(id)) {
    return null
  }

  const postId = Number(id)
  return Number.isSafeInteger(postId) ? postId : null
}

export async function GET(
  _request: Request,
  { params }: PostRouteContext,
): Promise<Response> {
  const { id } = await params
  const postId = parsePostId(id)

  if (postId === null) {
    return Response.json({ error: 'Invalid post ID' }, { status: 400 })
  }

  return Response.json({
    id: postId,
    title: `Post ${id}`,
    content: `This is the content for post ${id}`,
    createdAt: new Date().toISOString(),
  })
}

export async function PUT(
  request: Request,
  { params }: PostRouteContext,
): Promise<Response> {
  const { id } = await params
  const postId = parsePostId(id)

  if (postId === null) {
    return Response.json({ error: 'Invalid post ID' }, { status: 400 })
  }

  let body: PostInput

  try {
    body = (await request.json()) as PostInput
  } catch {
    return Response.json({ error: 'Invalid JSON body' }, { status: 400 })
  }

  if (body.title !== undefined && typeof body.title !== 'string') {
    return Response.json({ error: 'Title must be a string' }, { status: 400 })
  }

  if (body.content !== undefined && typeof body.content !== 'string') {
    return Response.json({ error: 'Content must be a string' }, { status: 400 })
  }

  const updatedPost: UpdatedPost = {
    id: postId,
    title: body.title || `Post ${id}`,
    content: body.content || `Updated content for post ${id}`,
    updatedAt: new Date().toISOString(),
  }

  return Response.json(updatedPost)
}

export async function DELETE(
  _request: Request,
  { params }: PostRouteContext,
): Promise<Response> {
  const { id } = await params

  if (parsePostId(id) === null) {
    return Response.json({ error: 'Invalid post ID' }, { status: 400 })
  }

  return Response.json({ message: `Post ${id} deleted successfully` })
}

