--- app/api/posts/[id]/route.ts
import type { PostInput, UpdatedPost } from '@/lib/posts'

type PostRouteContext = RouteContext<'/api/posts/[id]'>

function parsePostId(id: string): number | null {
  if (!/^\d+$/.test(id)) {
    return null
  }

  const postId = Number(id)
  return Number.isSafeInteger(postId) ? postId : null
}

export async function GET(
  _request: Request,
  { params }: PostRouteContext,
): Promise<Response> {
  const { id } = await params
  const postId = parsePostId(id)

  if (postId === null) {
    return Response.json({ error: 'Invalid post ID' }, { status: 400 })
  }

  return Response.json({
    id: postId,
    title: `Post ${id}`,
    content: `This is the content for post ${id}`,
    createdAt: new Date().toISOString(),
  })
}

export async function PUT(
  request: Request,
  { params }: PostRouteContext,
): Promise<Response> {
  const { id } = await params
  const postId = parsePostId(id)

  if (postId === null) {
    return Response.json({ error: 'Invalid post ID' }, { status: 400 })
  }

  let body: PostInput

  try {
    body = (await request.json()) as PostInput
  } catch {
    return Response.json({ error: 'Invalid JSON body' }, { status: 400 })
  }

  if (body.title !== undefined && typeof body.title !== 'string') {
    return Response.json({ error: 'Title must be a string' }, { status: 400 })
  }

  if (body.content !== undefined && typeof body.content !== 'string') {
    return Response.json({ error: 'Content must be a string' }, { status: 400 })
  }

  const updatedPost: UpdatedPost = {
    id: postId,
    title: body.title || `Post ${id}`,
    content: body.content || `Updated content for post ${id}`,
    updatedAt: new Date().toISOString(),
  }

  return Response.json(updatedPost)
}

export async function DELETE(
  _request: Request,
  { params }: PostRouteContext,
): Promise<Response> {
  const { id } = await params

  if (parsePostId(id) === null) {
    return Response.json({ error: 'Invalid post ID' }, { status: 400 })
  }

  return Response.json({ message: `Post ${id} deleted successfully` })
}
--- app/api/posts/route.ts
import type { ApiPost, CreatedPost, PostInput } from '@/lib/posts'

const posts: ApiPost[] = [
  { id: 1, title: 'First Post', content: 'This is the first post' },
  { id: 2, title: 'Second Post', content: 'This is the second post' },
]

export function GET(): Response {
  return Response.json(posts)
}

export async function POST(request: Request): Promise<Response> {
  let body: PostInput

  try {
    body = (await request.json()) as PostInput
  } catch {
    return Response.json({ error: 'Invalid JSON body' }, { status: 400 })
  }

  if (
    typeof body.title !== 'string' ||
    !body.title ||
    typeof body.content !== 'string' ||
    !body.content
  ) {
    return Response.json(
      { error: 'Title and content are required' },
      { status: 400 },
    )
  }

  const newPost: CreatedPost = {
    id: Date.now(),
    title: body.title,
    content: body.content,
    createdAt: new Date().toISOString(),
  }

  return Response.json(newPost, { status: 201 })
}
