--- lib/posts.ts
export interface BlogPost {
  id: number
  userId: number
  title: string
  body: string
}

export interface Comment {
  id: number
  postId: number
  name: string
  email: string
  body: string
}

export interface ApiPost {
  id: number
  title: string
  content: string
}

export interface CreatedPost extends ApiPost {
  createdAt: string
}

export interface UpdatedPost extends ApiPost {
  updatedAt: string
}

export interface PostInput {
  title?: unknown
  content?: unknown
}

const POSTS_URL = 'https://jsonplaceholder.typicode.com/posts'

async function fetchJson<T>(url: string, revalidate: number): Promise<T> {
  const response = await fetch(url, { next: { revalidate } })

  if (!response.ok) {
    throw new Error(`Request to ${url} failed with status ${response.status}`)
  }

  return response.json() as Promise<T>
}

export function getPosts(revalidate: number): Promise<BlogPost[]> {
  return fetchJson<BlogPost[]>(POSTS_URL, revalidate)
}

export function getRecentPosts(): Promise<BlogPost[]> {
  return fetchJson<BlogPost[]>(`${POSTS_URL}?_limit=5`, 0)
}

export function getPost(id: string): Promise<BlogPost> {
  return fetchJson<BlogPost>(`${POSTS_URL}/${encodeURIComponent(id)}`, 300)
}

export function getComments(id: string): Promise<Comment[]> {
  return fetchJson<Comment[]>(
    `${POSTS_URL}/${encodeURIComponent(id)}/comments`,
    300,
  )
}

export function isBlogPost(value: BlogPost): boolean {
  return Number.isInteger(value.id) && value.id > 0 && Boolean(value.title)
}
